(function(){'use strict';function failed(message){if(window.CET_APP_READY)return;var main=document.getElementById('main');if(!main)return;main.replaceChildren();var box=document.createElement('section');box.className='card empty';var h=document.createElement('h2');h.textContent='学习区加载失败';var p=document.createElement('p');p.textContent=message+'。请检查网络后刷新，学习记录仍保留在此设备。';var b=document.createElement('button');b.textContent='重新加载';b.onclick=function(){location.reload();};box.append(h,p,b);main.append(box);}window.addEventListener('error',function(e){if(e.target&&e.target.tagName==='SCRIPT')failed('无法加载脚本 '+e.target.getAttribute('src'));else if(e.message)failed(e.message);},true);window.addEventListener('unhandledrejection',function(e){failed(e.reason&&e.reason.message||'初始化发生异常');});})();
